<script module lang="ts">
    import { search } from '@/routes';
    export const layout = { breadcrumbs: [{ title: 'Pencarian', href: search() }] };
</script>
<script lang="ts">
    import { Link } from '@inertiajs/svelte'; import SearchIcon from '@lucide/svelte/icons/search'; import AppHead from '@/components/AppHead.svelte'; import { Input } from '@/components/ui/input'; import { toUrl } from '@/lib/utils'; import TaskController from '@/actions/App/Http/Controllers/TaskController'; import ProjectController from '@/actions/App/Http/Controllers/ProjectController';
    type Workspace = { id: string; name: string } | null; type Project = { id: string; name: string; identifier: string }; type Task = { id: string; identifier: string; title: string; project: Project | null; status: string };
    let { workspace, query, projects, tasks }: { workspace: Workspace; query: string; projects: Project[]; tasks: Task[] } = $props();
</script>
<AppHead title="Pencarian" /><div class="mx-auto flex w-full max-w-4xl flex-col gap-6 px-4 py-6 sm:px-6 lg:px-8"><header><h1 class="text-2xl font-semibold tracking-tight">Pencarian</h1><p class="mt-1 text-sm text-muted-foreground">Cari Project dan Task yang dapat Anda akses.</p></header><form method="get" action={toUrl(search())} class="relative"><SearchIcon class="pointer-events-none absolute left-3 top-3 size-4 text-muted-foreground" aria-hidden="true" /><Input name="q" value={query} placeholder="Cari nama, ID, judul, atau deskripsi" class="min-h-11 pl-9" autofocus /></form>{#if query === ''}<p class="rounded-lg border border-dashed px-6 py-10 text-center text-sm text-muted-foreground">Masukkan kata kunci untuk mulai mencari.</p>{:else if projects.length === 0 && tasks.length === 0}<p class="rounded-lg border border-dashed px-6 py-10 text-center text-sm text-muted-foreground">Tidak ada hasil untuk “{query}”.</p>{:else}<div class="grid gap-6 sm:grid-cols-2"><section class="rounded-lg border bg-card"><h2 class="border-b px-4 py-3 text-sm font-semibold">Project</h2><div class="divide-y">{#each projects as project (project.id)}<Link href={toUrl(ProjectController.show({ workspace: workspace?.id ?? '', project: project.id }))} class="block px-4 py-3 hover:bg-muted/40"><p class="font-mono text-xs text-muted-foreground">{project.identifier}</p><p class="mt-1 text-sm font-medium">{project.name}</p></Link>{/each}</div></section><section class="rounded-lg border bg-card"><h2 class="border-b px-4 py-3 text-sm font-semibold">Task</h2><div class="divide-y">{#each tasks as task (task.id)}<Link href={task.project ? toUrl(TaskController.show({ workspace: workspace?.id ?? '', project: task.project.id, task: task.id })) : '#'} class="block px-4 py-3 hover:bg-muted/40"><p class="font-mono text-xs text-muted-foreground">{task.identifier}</p><p class="mt-1 text-sm font-medium">{task.title}</p><p class="mt-1 text-xs text-muted-foreground">{task.project?.identifier ?? 'Project tidak tersedia'}</p></Link>{/each}</div></section></div>{/if}</div>
